import subprocess, os, pathlib, shutil
REF="/workspace/executable"
BASE="/tmp/t2"
HOME="/tmp/fakehome_empty"
os.makedirs(HOME, exist_ok=True)
def reset(files=None):
    shutil.rmtree(BASE, ignore_errors=True); os.makedirs(BASE, exist_ok=True)
    if files:
        for name, content in files.items():
            p=pathlib.Path(BASE+"/"+name)
            p.parent.mkdir(parents=True, exist_ok=True)
            if isinstance(content, bytes): p.write_bytes(content)
            else: p.write_text(content)
def run(args, inp=b"a", term="xterm", home=HOME, cwd=None, timeout=3, env_extra=None):
    env={**os.environ}
    if term is None: env.pop("TERM",None)
    else: env["TERM"]=term
    if home is not None: env["HOME"]=home
    if env_extra:
        for k,v in env_extra.items():
            if v is None: env.pop(k,None)
            else: env[k]=v
    try:
        p=subprocess.run([REF]+args, cwd=cwd or BASE, capture_output=True, env=env, input=inp, timeout=timeout)
        return p
    except subprocess.TimeoutExpired as e:
        class P: pass
        p=P(); p.returncode="TIMEOUT"; p.stdout=e.stdout or b""; p.stderr=e.stderr or b""; return p
def show(p, files=None):
    print("rc",p.returncode); print("out",p.stdout); print("err",p.stderr)
    if files:
        for f in files:
            pp=pathlib.Path(BASE+"/"+f)
            print(f, repr(pp.read_bytes()) if pp.exists() else "MISSING")
PY
