    ArgDef { long: "bin-check-bytes", short: None, value_name: Some("BYTES") },
    ArgDef { long: "mmap-bytes", short: None, value_name: Some("BYTES") },
];
fn find_long(name: &str) -> Option<ArgDef> {
    FLAG_DEFS.iter().chain(OPTION_DEFS.iter()).cloned().find(|d| d.long == name)
}
fn display_arg(d: &ArgDef) -> String {
