"#, bin = bin, mt = default_max_threads())
}
fn full_usage(bin: &str) -> String {
    format!("    {} [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...\n", bin)
}
fn smart_usage(bin: &str, used: &BTreeSet<&'static str>) -> String {
    if used.is_empty() { return full_usage(bin); }
    let mut s = format!("    {} <KEYWORD> <REPLACEMENT>", bin);
    for long in used {
        if let Some(d) = find_long(long) {
            s.push(' ');
            s.push_str(&display_arg(&d));
        }
    }
    s.push('\n');
    s
}
fn usage_with_defaults(bin: &str, used: &BTreeSet<&'static str>) -> String {
    let mut u = used.clone();
    for d in OPTION_DEFS { u.insert(d.long); }
    smart_usage(bin, &u)
}
fn cli_exit(msg: String, code: i32) -> ! {
    if code == 0 {
        let _ = io::stdout().write_all(msg.as_bytes());
    } else {
        let _ = io::stderr().write_all(msg.as_bytes());
    }
    process::exit(code);
}
fn err_unknown(bin: &str, shown: &str, used: &BTreeSet<&'static str>, suggestion: Option<ArgDef>) -> ! {
    let mut u = used.clone();
    if let Some(d) = suggestion { u.insert(d.long); }
    let mut msg = format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n", shown);
    if let Some(d) = suggestion {
        msg.push_str(&format!("\tDid you mean \u{1b}[32m--\u{1b}[0m\u{1b}[32m{}\u{1b}[0m?\n", d.long));
    }
    msg.push_str(&format!("\nUSAGE:\n{}\nFor more information try --help\n", smart_usage(bin, &u)));
    cli_exit(msg, 1);
}
// Jaro-Winkler for clap-style suggestions
fn jaro(s1: &str, s2: &str) -> f64 {
    let a: Vec<char> = s1.chars().collect();
    let b: Vec<char> = s2.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    let max_len = a.len().max(b.len());
    let search = (max_len / 2).saturating_sub(1);
    let mut b_matched = vec![false; b.len()];
    let mut a_matched = vec![false; a.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = i.saturating_sub(search);
        let end = (i + search + 1).min(b.len());
        for j in start..end {
            if !b_matched[j] && a[i] == b[j] {
                a_matched[i] = true; b_matched[j] = true; matches += 1; break;
            }
        }
    }
    if matches == 0 { return 0.0; }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if a_matched[i] {
            while !b_matched[k] { k += 1; }
            if a[i] != b[k] { transpositions += 1; }
            k += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (transpositions / 2) as f64) / m) / 3.0
}
fn jaro_winkler(s1: &str, s2: &str) -> f64 {
    let j = jaro(s1, s2);
    let prefix = s1.chars().zip(s2.chars()).take(4).take_while(|(a,b)| a==b).count();
    j + prefix as f64 * 0.1 * (1.0 - j)
}
fn suggestion_for(name: &str) -> Option<ArgDef> {
    let mut best: Option<(f64, ArgDef)> = None;
    for d in FLAG_DEFS.iter().chain(OPTION_DEFS.iter()) {
        let conf = jaro_winkler(name, d.long);
        if conf > 0.8 {
            if best.map_or(true, |(c,_)| conf > c) { best = Some((conf, *d)); }
        }
    }
    best.map(|(_,d)| d)
}

#[derive(Default)]
struct Cli {
    flags: HashSet<&'static str>,
    flag_counts: HashMap<&'static str, usize>,
    options: HashMap<&'static str, Vec<Option<String>>>,
    option_values: HashMap<&'static str, usize>,
    positionals: Vec<String>,
    used: BTreeSet<&'static str>,
    first_order: Vec<&'static str>,
}
impl Cli {
    fn record(&mut self, d: ArgDef) {
        if !self.used.contains(d.long) { self.first_order.push(d.long); }
        self.used.insert(d.long);
    }
    fn has(&self, long: &str) -> bool { self.flags.contains(long) }
}

