fn parse_cli(bin: &str) -> Cli {
    let raw: Vec<OsString> = env::args_os().skip(1).collect();
    if raw.iter().any(|a| a.to_str().is_none()) { fake_utf8_panic(&raw); }
    let args: Vec<String> = raw.into_iter().map(|a| a.to_string_lossy().into_owned()).collect();
    let mut cli = Cli::default();
    let mut end_opts = false;
    let mut pending: Option<ArgDef> = None;
    let mut i = 0usize;
    while i < args.len() {
        let tok = args[i].clone();
        i += 1;
        if let Some(opt) = pending.take() {
            if tok == "--" {
                cli.options.entry(opt.long).or_default().push(None);
                end_opts = true;
                continue;
            } else if tok.len() > 1 && tok.starts_with('-') {
                cli.options.entry(opt.long).or_default().push(None);
                // fall through to process tok as a flag/option
            } else {
                cli.options.entry(opt.long).or_default().push(Some(tok));
                continue;
            }
        }
        if end_opts {
            cli.positionals.push(tok);
            continue;
        }
        if tok == "--" {
            end_opts = true;
            continue;
        }
        if tok.starts_with("--") {
            // long: strip all leading '-'
            let rest = tok.trim_start_matches('-');
            let (name, eq_val) = match rest.find('=') {
                Some(p) => (&rest[..p], Some(rest[p+1..].trim_start_matches('=').to_string())),
                None => (rest, None),
            };
            if name.is_empty() {
                err_unknown(bin, "--", &cli.used, None);
            }
            let name_owned = name.to_string();
            match find_long(&name_owned) {
                None => {
                    let sugg = suggestion_for(&name_owned);
                    err_unknown(bin, &format!("--{}", name_owned), &cli.used, sugg);
                }
                Some(d) => {
                    if d.long == "help" {
                        cli_exit(help_text(bin), 0);
                    }
                    if d.long == "version" {
                        cli_exit("ambr 0.6.0\n".to_string(), 0);
                    }
                    cli.record(d);
                    if d.value_name.is_some() {
                        if let Some(v) = eq_val {
                            cli.options.entry(d.long).or_default().push(Some(v));
                        } else {
                            pending = Some(d);
                        }
                    } else {
                        cli.flags.insert(d.long);
                        *cli.flag_counts.entry(d.long).or_insert(0) += 1;
                    }
                }
            }
            continue;
        }
        if tok.len() > 1 && tok.starts_with('-') {
            // short cluster (single leading dash; "--" handled above)
            let cluster: Vec<char> = tok[1..].chars().collect();
            for ch in cluster {
                match ch {
                    'h' => cli_exit(help_text(bin), 0),
                    'V' => cli_exit("ambr 0.6.0\n".to_string(), 0),
                    'r' => {
                        let d = find_long("regex").unwrap();
                        cli.record(d);
                        cli.flags.insert("regex");
                        *cli.flag_counts.entry("regex").or_insert(0) += 1;
                    }
                    _ => {
                        err_unknown(bin, &format!("-{}", ch), &cli.used, None);
                    }
                }
            }
            continue;
        }
        cli.positionals.push(tok);
    }
    if let Some(opt) = pending.take() {
        cli.options.entry(opt.long).or_default().push(None);
    }
    // missing required
    if cli.positionals.len() < 2 {
        let mut msg = String::from("error: The following required arguments were not provided:\n");
        if cli.positionals.is_empty() { msg.push_str("    <KEYWORD>\n"); }
        msg.push_str("    <REPLACEMENT>\n");
        msg.push_str(&format!("\nUSAGE:\n{}\nFor more information try --help\n", usage_with_defaults(bin, &cli.used)));
        cli_exit(msg, 1);
    }
    // validate values / duplicates per first-occurrence order
    for long in cli.first_order.clone() {
        let d = find_long(long).unwrap();
        if d.value_name.is_some() {
            let occs = cli.options.get(long).cloned().unwrap_or_default();
            for v in &occs {
                if let Some(vs) = v {
                    match vs.parse::<usize>() {
                        Ok(n) => { cli.option_values.insert(long, n); }
                        Err(e) => {
                            cli_exit(format!("error: Invalid value for '{}': {}\n", display_arg(&d), e.to_string()), 1);
                        }
                    }
                }
            }
            if occs.len() > 1 {
                let msg = format!("error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n{}\nFor more information try --help\n", display_arg(&d), usage_with_defaults(bin, &cli.used));
                cli_exit(msg, 1);
            }
        } else {
            if cli.flag_counts.get(long).cloned().unwrap_or(0) > 1 {
                let msg = format!("error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n{}\nFor more information try --help\n", display_arg(&d), usage_with_defaults(bin, &cli.used));
                cli_exit(msg, 1);
            }
        }
    }
    cli
}
