fn load_config() -> FileConfig {
    let mut candidates: Vec<PathBuf> = Vec::new();
    if let Some(home) = dirs::home_dir() {
        candidates.push(home.join(".ambr.toml"));
    }
    if let Some(cfg) = dirs::config_dir() {
        candidates.push(cfg.join("amber").join("ambr.toml"));
    }
    candidates.push(PathBuf::from("/etc/amber/ambr.toml"));
    for cand in candidates {
        if cand.symlink_metadata().is_ok() {
            // selected: read or default, no fallthrough
            if let Ok(text) = fs::read_to_string(&cand) {
                if let Ok(cfg) = toml::from_str::<FileConfig>(&text) {
                    return cfg;
                }
            }
            return FileConfig::default();
        }
    }
    FileConfig::default()
}

