fn strip_padding(raw: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(raw.len());
    let mut i = 0;
    while i < raw.len() {
        if i + 1 < raw.len() && raw[i] == b'$' && raw[i+1] == b'<' {
            if let Some(pos) = raw[i+2..].iter().position(|&b| b == b'>') {
                i = i + 2 + pos + 1;
                continue;
            }
        }
        out.push(raw[i]);
        i += 1;
    }
    out
}
fn expand_cap(raw: &[u8], params: &[Parameter]) -> Option<Vec<u8>> {
    let stripped = strip_padding(raw);
    let mut v = Vec::new();
    let mut ctx = Context::default();
    stripped.as_slice().expand(&mut v, params, &mut ctx).ok()?;
    Some(v)
}
struct TermSpec {
    max_colors: Option<i32>,
    setaf: Option<Vec<u8>>,
    setf: Option<Vec<u8>>,
    sgr0: Option<Vec<u8>>,
}
impl TermSpec {
    fn from_env() -> Option<Self> {
        let db = Database::from_env().ok()?;
        let max_colors = db.get::<cap::MaxColors>().map(|x| { let i: i32 = x.into(); i });
        let setaf = db.get::<cap::SetAForeground>().map(|x| x.as_ref().to_vec());
        let setf = db.get::<cap::SetForeground>().map(|x| x.as_ref().to_vec());
        let sgr0 = db.get::<cap::ExitAttributeMode>().map(|x| x.as_ref().to_vec());
        Some(TermSpec { max_colors, setaf, setf, sgr0 })
    }
    fn fg_bytes(&self, color: u8) -> Option<Vec<u8>> {
        if let Some(max) = self.max_colors {
            if (color as i32) >= max { return None; }
        }
        if let Some(capstr) = &self.setaf {
            return expand_cap(capstr, &[Parameter::Number(color as i32)]);
        }
        if let Some(capstr) = &self.setf {
            const REMAP: [i32; 8] = [0,4,2,6,1,5,3,7];
            let idx = REMAP.get(color as usize).cloned().unwrap_or(color as i32);
            return expand_cap(capstr, &[Parameter::Number(idx)]);
        }
        None
    }
    fn reset_bytes(&self) -> Option<Vec<u8>> {
        let capstr = self.sgr0.as_ref()?;
        expand_cap(capstr, &[])
    }
}
