}
struct Console<W: Write> {
    writer: W,
    spec: Rc<TermSpec>,
    color_enabled: bool,
    cur: Option<u8>,
}
impl<W: Write> Console<W> {
    fn new(writer: W, spec: Rc<TermSpec>, color_enabled: bool) -> Self {
        Console { writer, spec, color_enabled, cur: None }
    }
    fn fg(&mut self, c: u8) -> R<()> {
        if !self.color_enabled { return Ok(()); }
        if self.cur == Some(c) { return Ok(()); }
        let bytes = self.spec.fg_bytes(c).ok_or(Silent)?;
        self.writer.write_all(&bytes)?;
        self.cur = Some(c);
        Ok(())
    }
    fn write_str(&mut self, s: &str) -> R<()> { self.writer.write_all(s.as_bytes())?; Ok(()) }
    fn write_bytes(&mut self, b: &[u8]) -> R<()> { self.writer.write_all(b)?; Ok(()) }
    fn flush(&mut self) -> R<()> { self.writer.flush()?; Ok(()) }
    fn reset(&mut self) -> R<()> {
        let bytes = self.spec.reset_bytes().ok_or(Silent)?;
        self.writer.write_all(&bytes)?;
        self.writer.flush()?;
        self.cur = None;
        Ok(())
    }
}
