            let rest = tok.trim_start_matches('-');
            let (name, eq_val) = match rest.find('=') {
                Some(p) => (&rest[..p], Some(rest[p+1..].trim_start_matches('=').to_string())),
                None => (rest, None),
            };
            if name.is_empty() {
                err_unknown(bin, "--", &cli.used, None);
            }
            let name_owned = name.to_string();
            match find_long(&name_owned) {
                None => {
                    let sugg = suggestion_for(&name_owned);
                    err_unknown(bin, &format!("--{}", name_owned), &cli.used, sugg);
                }
                Some(d) => {
                    if d.long == "help" {
                        cli_exit(help_text(bin), 0);
                    }
                    if d.long == "version" {
                        cli_exit("ambr 0.6.0\n".to_string(), 0);
                    }
                    cli.record(d);
                    if d.value_name.is_some() {
                        if let Some(v) = eq_val {
