            let cluster: Vec<char> = tok[1..].chars().collect();
            for ch in cluster {
                match ch {
                    'h' => cli_exit(help_text(bin), 0),
                    'V' => cli_exit("ambr 0.6.0\n".to_string(), 0),
                    'r' => {
                        let d = find_long("regex").unwrap();
                        cli.record(d);
                        cli.flags.insert("regex");
                        *cli.flag_counts.entry("regex").or_insert(0) += 1;
                    }
                    _ => {
                        err_unknown(bin, &format!("-{}", ch), &cli.used, None);
                    }
