fn strip_padding(raw: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(raw.len());
    let mut i = 0;
    while i < raw.len() {
        if i + 1 < raw.len() && raw[i] == b'$' && raw[i+1] == b'<' {
            if let Some(pos) = raw[i+2..].iter().position(|&b| b == b'>') {
                i = i + 2 + pos + 1;
                continue;
            }
        }
        out.push(raw[i]);
        i += 1;
    }
    out
}
fn expand_cap(raw: &[u8], params: &[Parameter]) -> Option<Vec<u8>> {
    let stripped = strip_padding(raw);
    let mut v = Vec::new();
    let mut ctx = Context::default();
    stripped.as_slice().expand(&mut v, params, &mut ctx).ok()?;
    Some(v)
}
