        let result: io::Result<()> = (|| {
            let parent = canonical.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("/"));
            let mut tmp = tempfile::NamedTempFile::new_in(&parent)?;
            tmp.write_all(new_data)?;
            tmp.flush()?;
            let perms = orig_meta.permissions();
            fs::set_permissions(tmp.path(), perms)?;
            if self.eff.preserve_time {
                if let Ok(mtime) = orig_meta.modified() {
                    set_mtime(tmp.path(), mtime);
                }
            }
            tmp.persist(canonical).map_err(|e| e.error)?;
            Ok(())
        })();
        if let Err(e) = result {
            self.err_error(&format!("Error: {} @ {:?}\n", kind_phrase(e.kind()), display_path))?;
        }
        Ok(())
    }

    fn process_candidate(&mut self, display_path: &Path) -> R<()> {
        if self.quit { return Ok(()); }
        let t0 = Instant::now();
        // read file
        let data = match fs::read(display_path) {
            Ok(d) => d,
            Err(e) => {
                self.err_error(&format!("Error: {} @ {:?}\n\n", kind_phrase(e.kind()), display_path))?;
                return Ok(());
            }
        };
        // binary check
        if !self.eff.binary {
            let n = self.eff.bin_check_bytes.min(data.len());
            if data[..n].iter().any(|&b| b < 9) {
                self.stats.match_accum += t0.elapsed();
                self.print_skip("(binary)", display_path)?;
                return Ok(());
            }
        }
        // canonical dedup
        let canonical = match fs::canonicalize(display_path) {
            Ok(c) => c,
            Err(e) => {
                self.err_error(&format!("Error: {} @ {:?}\n\n", kind_phrase(e.kind()), display_path))?;
                return Ok(());
            }
        };
        if self.seen.contains(&canonical) {
            self.stats.match_accum += t0.elapsed();
            return Ok(());
        }
        self.seen.insert(canonical.clone());
        let orig_meta = match fs::metadata(&canonical) {
            Ok(m) => m,
            Err(_) => {
                self.stats.match_accum += t0.elapsed();
                return Ok(());
            }
        };
        if self.eff.size_per_thread == 0 && !data.is_empty() {
            // original matcher divides by zero and hangs; keep simple
            // fall through (treated as one chunk by us) - see notes
        }
        let mut matches = self.find_matches(&data);
        self.stats.match_accum += t0.elapsed();
        if matches.is_empty() { return Ok(()); }
        matches.sort_by_key(|m| m.start);
        // path string for interactive display
        let path_str = display_path.to_string_lossy().into_owned();
        let mut new_data: Vec<u8> = Vec::with_capacity(data.len());
        let mut cursor = 0usize;
        for m in &matches {
            let do_replace: bool;
            if self.eff.interactive && !self.do_all {
                let ans = self.ask(&data, &path_str, m)?;
                match ans {
                    'q' => { self.quit = true; return Ok(()); }
                    'a' => { self.do_all = true; do_replace = true; }
                    'y' => { do_replace = true; }
                    _ => { do_replace = false; }
                }
            } else {
                do_replace = true;
            }
            if m.start < cursor {
                // overlapping (only possible with chunk bugs in original); skip safely
                continue;
            }
            new_data.extend_from_slice(&data[cursor..m.start]);
            if do_replace {
                new_data.extend_from_slice(&m.replacement);
            } else {
                new_data.extend_from_slice(&data[m.start..m.end]);
            }
            cursor = m.end;
        }
        new_data.extend_from_slice(&data[cursor..]);
        self.write_replaced(display_path, &canonical, &orig_meta, &new_data)?;
        Ok(())
    }

    fn walk_dir(&mut self, dir: &Path, inherited: &Option<Gitignore>) -> R<()> {
        if self.quit { return Ok(()); }
        let tfind = Instant::now();
        let rd = match fs::read_dir(dir) {
            Ok(r) => r,
            Err(e) => {
                self.stats.find_accum += tfind.elapsed();
                self.print_finder_error(&e, dir)?;
                return Ok(());
            }
        };
        let entries: Vec<_> = rd.flatten().collect();
        // local gitignore overrides inherited
        let current: Option<Gitignore> = if self.eff.skip_gitignore && entries.iter().any(|e| e.file_name() == ".gitignore") {
            let (gi, _e) = Gitignore::new(dir.join(".gitignore"));
            Some(gi)
        } else {
            inherited.clone()
        };
        self.stats.find_accum += tfind.elapsed();
        for entry in entries {
            if self.quit { return Ok(()); }
            let path = entry.path();
            let meta = match entry.metadata() {
                Ok(m) => m,
                Err(_) => continue,
            };
            let is_symlink = entry.file_type().map(|t| t.is_symlink()).unwrap_or(false);
            if meta.is_dir() {
                let mut skipped = false;
                let fname = entry.file_name();
                if self.eff.skip_vcs && (fname == ".git" || fname == ".hg" || fname == ".svn" || fname == ".bzr") {
                    self.print_skip("(vcs file)", &path)?;
                    skipped = true;
                }
                if self.eff.skip_gitignore {
                    if let Some(gi) = &current {
                        if gi.matched(&path, true).is_ignore() {
                            self.print_skip("(.gitignore)", &path)?;
                            skipped = true;
                        }
                    }
                }
                if skipped { continue; }
                if is_symlink && !self.eff.symlink { continue; }
                if self.eff.recursive {
                    self.walk_dir(&path, &current)?;
                }
            } else if meta.is_file() {
                if self.eff.skip_gitignore {
                    if let Some(gi) = &current {
                        if gi.matched(&path, false).is_ignore() {
                            self.print_skip("(.gitignore)", &path)?;
                            continue;
                        }
                    }
                }
                if is_symlink && !self.eff.symlink { continue; }
                self.process_candidate(&path)?;
            } else {
                continue;
            }
        }
        Ok(())
    }

    fn process_root(&mut self, root_str: &str) -> R<()> {
        let root = Path::new(root_str);
        let canonical = match fs::canonicalize(root) {
            Ok(c) => c,
            Err(e) => {
                self.print_finder_error(&e, root)?;
                if self.eff.skip_gitignore && self.eff.parent_ignore {
                    self.print_finder_error(&e, root)?;
                }
                return Ok(());
            }
        };
        let parent = self.parent_matcher(root, &canonical)?;
        if canonical.is_file() {
            if self.eff.skip_gitignore {
                if let Some(gi) = &parent {
                    if gi.matched(root, false).is_ignore() {
                        self.print_skip("(.gitignore)", root)?;
                        return Ok(());
                    }
                }
            }
            self.process_candidate(root)?;
        } else {
            // directory or other: walk (read_dir error for non-dir)
            self.walk_dir(root, &parent)?;
        }
        Ok(())
    }

    fn print_statistics(&mut self) -> R<()> {
        let max_t = self.eff.max_threads;
        let workers = std::cmp::min(max_t, 8).max(1);
        let total_elapsed = self.stats.elapsed();
        let find_d = self.stats.find_accum;
        let match_d = self.stats.find_accum + self.stats.match_accum;
        let sort_d = match_d;
        let fmt = |d: Duration| -> String {
            // seconds as f64 like the original
            let s = d.as_secs_f64();
            format!("{}", s)
        };
        let mut s = String::new();
        s.push_str(&format!("\nStatistics\n  Max threads: {}\n\n  Consumed time ( busy / total )\n", max_t));
        s.push_str(&format!("    Find     : 0s / {}s\n", fmt(find_d)));
        for i in 0..workers {
            let d = if i == 0 { match_d } else { find_d + Duration::from_micros(20) };
            s.push_str(&format!("    Match{:02}  : 0s / {}s\n", i, fmt(d)));
        }
        s.push_str(&format!("    Sort     : 0s / {}s\n", fmt(sort_d)));
        s.push_str(&format!("    Replace  : 0s / {}s\n", fmt(total_elapsed)));
        s.push('\n');
        self.err.fg(color::CYAN)?;
        self.err.write_str(&s)?;
        self.err.flush()
    }
}

fn set_mtime(path: &Path, mtime: SystemTime) {
    // utimensat with atime = UTIME_OMIT, mtime = given
    use std::os::unix::ffi::OsStrExt;
    let dur = mtime.duration_since(SystemTime::UNIX_EPOCH).unwrap_or(Duration::ZERO);
    let times = [
        libc::timespec { tv_sec: 0, tv_nsec: libc::UTIME_OMIT as i64 },
        libc::timespec { tv_sec: dur.as_secs() as i64, tv_nsec: dur.subsec_nanos() as i64 },
    ];
    let cpath = match std::ffi::CString::new(path.as_os_str().as_bytes()) { Ok(c) => c, Err(_) => return };
    unsafe {
        libc::utimensat(libc::AT_FDCWD, cpath.as_ptr(), times.as_ptr(), 0);
    }
}

fn run() -> i32 {
    let bin = bin_name();
    let cli = parse_cli(&bin);
    let cfg = load_config();
    let eff = Effective {
        regex: cfg.regex || cli.has("regex"),
        column: cfg.column || cli.has("column"),
        row: cfg.row || cli.has("row"),
        binary: cfg.binary || cli.has("binary"),
        statistics: cfg.statistics || cli.has("statistics"),
        print_skipped: cfg.skipped || cli.has("skipped") || cli.has("verbose"),
        preserve_time: cfg.preserve_time || cli.has("preserve-time"),
        interactive: cfg.interactive && !cli.has("no-interactive"),
        recursive: cfg.recursive && !cli.has("no-recursive"),
        symlink: cfg.symlink && !cli.has("no-symlink"),
        color: cfg.color && !cli.has("no-color"),
        file: cfg.file && !cli.has("no-file"),
        skip_vcs: cfg.skip_vcs && !cli.has("no-skip-vcs"),
        skip_gitignore: cfg.skip_gitignore && !cli.has("no-skip-gitignore"),
        fixed_order: cfg.fixed_order && !cli.has("no-fixed-order"),
        parent_ignore: cfg.parent_ignore && !cli.has("no-parent-ignore"),
        tbm: cli.has("tbm"),
        sse: cli.has("sse"),
        verbose: cli.has("verbose"),
        max_threads: cli.opt_usize("max-threads", default_max_threads()),
        size_per_thread: cli.opt_usize("size-per-thread", 1048576),
        bin_check_bytes: cli.opt_usize("bin-check-bytes", 256),
        mmap_bytes: cli.opt_usize("mmap-bytes", 1048576),
    };
    // terminals
    let spec = match TermSpec::from_env() {
        Some(s) => Rc::new(s),
        None => return 1,
    };
    let mut out = Console::new(io::stdout(), spec.clone(), eff.color);
    let mut err = Console::new(io::stderr(), spec.clone(), eff.color);
    // keyword / replacement
    let keyword_arg = &cli.positionals[0];
    let rep_arg = &cli.positionals[1];
    let keyword: String;
    let replacement: String;
    if cli.has("key-from-file") {
        match load_string_file(keyword_arg) {
            Ok(s) => {
                if s.is_empty() {
                    let _ = err.fg(color::RED);
                    let _ = err.write_str(&format!("Error: file is empty @ {:?}\n", Path::new(keyword_arg)));
                    let _ = out.reset();
                    let _ = err.reset();
                    return 1;
                }
                keyword = s;
            }
            Err(te) => {
                // if fg fails, mimic silent failure: check first
                if err.fg(color::RED).is_err() { return 1; }
                let _ = err.write_str(&format!("Error: {} @ {:?}\n", te.msg, te.path));
                let _ = out.reset();
                let _ = err.reset();
                return 1;
            }
        }
    } else {
        keyword = escape_keyword(keyword_arg);
    }
    if cli.has("rep-from-file") {
        match load_string_file(rep_arg) {
            Ok(s) => { replacement = s; }
            Err(te) => {
                if err.fg(color::RED).is_err() { return 1; }
                let _ = err.write_str(&format!("Error: {} @ {:?}\n", te.msg, te.path));
                let _ = out.reset();
                let _ = err.reset();
                return 1;
            }
        }
    } else {
        replacement = escape_keyword(rep_arg);
    }
    let regex = if eff.regex {
        RegexBuilder::new(&keyword).multi_line(true).build().ok()
    } else { None };
    let mut runner = Runner {
        out, err, eff, keyword, replacement, regex,
        seen: HashSet::new(), do_all: false, quit: false,
        stats: Stats { start: Some(Instant::now()), find_accum: Duration::ZERO, match_accum: Duration::ZERO },
    };
    let roots: Vec<String> = if cli.positionals.len() > 2 {
        cli.positionals[2..].to_vec()
    } else {
        vec![".".to_string()]
    };
    for root in &roots {
        if runner.quit { break; }
        if runner.process_root(root).is_err() {
            return 1;
        }
    }
    if runner.eff.statistics && !runner.quit {
        if runner.print_statistics().is_err() { return 1; }
    }
    let r1 = runner.out.reset();
    let r2 = runner.err.reset();
    if r1.is_err() || r2.is_err() { return 1; }
    0
}

fn main() {
    process::exit(run());
}
