// ---------- misc helpers ----------
fn escape_keyword(s: &str) -> String {
    s.replace("\\n", "\n").replace("\\t", "\t").replace("\\r", "\r").replace("\\\\", "\\")
}
fn kind_phrase(k: io::ErrorKind) -> &'static str {
    match k {
        io::ErrorKind::NotFound => "file not found",
        io::ErrorKind::PermissionDenied => "permission denied",
        _ => "unknown",
    }
}
struct TopError {
    msg: String,
    path: PathBuf,
}
fn load_string_file(path_str: &str) -> Result<String, TopError> {
    let path = Path::new(path_str);
    let mut f = File::open(path).map_err(|e| TopError { msg: kind_phrase(e.kind()).to_string(), path: path.to_path_buf() })?;
    let mut s = String::new();
    if f.read_to_string(&mut s).is_err() { s.clear(); }
    Ok(s)
}
fn char_display_width(c: char) -> usize {
    // old unicode-width semantics: control = 1 (None -> 1), combining = 0, wide = 2
    if (c as u32) < 0x20 || ((c as u32) >= 0x7f && (c as u32) < 0xa0) {
        return 1;
    }
    UnicodeWidthChar::width(c)
}
fn str_display_width(s: &str) -> usize { s.chars().map(char_display_width).sum() }

fn char_len_at(data: &[u8], i: usize) -> usize {
    let b = data[i];
    if b < 0x80 { return 1; }
    // valid UTF-8 ?
    let expected = match b {
        0xC2..=0xDF => Some(2),
        0xE0..=0xEF => Some(3),
        0xF0..=0xF4 => Some(4),
        _ => None,
    };
    if let Some(len) = expected {
        if i + len <= data.len() && std::str::from_utf8(&data[i..i+len]).is_ok() {
            return len;
        }
    }
    // Shift_JIS double byte
    if ((0x81..=0x9F).contains(&b) || (0xE0..=0xEF).contains(&b)) && i + 1 < data.len() {
        let n = data[i+1];
        if (0x40..=0x7E).contains(&n) || (0x80..=0xFC).contains(&n) {
            return 2;
        }
    }
    1
}

#[derive(Clone)]
struct MatchInfo {
    start: usize,
    end: usize,
    replacement: Vec<u8>,
}

struct Effective {
    regex: bool,
    column: bool,
    row: bool,
    binary: bool,
    statistics: bool,
    print_skipped: bool,
    preserve_time: bool,
    interactive: bool,
    recursive: bool,
    symlink: bool,
    color: bool,
    file: bool,
    skip_vcs: bool,
    skip_gitignore: bool,
    fixed_order: bool,
    parent_ignore: bool,
    tbm: bool,
    sse: bool,
    verbose: bool,
    max_threads: usize,
    size_per_thread: usize,
    bin_check_bytes: usize,
    mmap_bytes: usize,
}

#[derive(Default)]
struct Stats {
    start: Option<Instant>,
    find_accum: Duration,
    match_accum: Duration,
}
impl Stats {
    fn elapsed(&self) -> Duration { self.start.map(|s| s.elapsed()).unwrap_or(Duration::ZERO) }
}

struct Runner {
    out: Console<io::Stdout>,
    err: Console<io::Stderr>,
    eff: Effective,
    keyword: String,
    replacement: String,
    regex: Option<Regex>,
    seen: HashSet<PathBuf>,
    do_all: bool,
    quit: bool,
    stats: Stats,
}

impl Runner {
    // --- stderr message helpers ---
    fn err_info(&mut self, text: &str) -> R<()> {
        self.err.fg(color::CYAN)?;
        self.err.write_str(text)?;
        self.err.flush()
    }
    fn err_error(&mut self, text: &str) -> R<()> {
        self.err.fg(color::RED)?;
        self.err.write_str(text)?;
        self.err.flush()
    }
    fn print_skip(&mut self, reason: &str, path: &Path) -> R<()> {
        if self.eff.print_skipped {
            self.err_info(&format!("Skip {:<12}: {:?}\n", reason, path))?;
        }
        Ok(())
    }
    fn print_finder_error(&mut self, e: &io::Error, path: &Path) -> R<()> {
        self.err_error(&format!("Error: {} @ {}\n", e, path.display()))
    }

    // --- parent ignore ---
    fn dir_contains_gitignore(dir: &Path) -> bool {
        if let Ok(rd) = fs::read_dir(dir) {
            for ent in rd.flatten() {
                if ent.file_name() == ".gitignore" { return true; }
            }
        }
        false
    }
    fn parent_matcher(&mut self, root: &Path, canonical: &Path) -> R<Option<Gitignore>> {
        if !(self.eff.skip_gitignore && self.eff.parent_ignore) {
            return Ok(None);
        }
        let (start_original, check_count): (PathBuf, usize) = if canonical.is_dir() {
            let mut p = root.to_path_buf();
            p.push("..");
            (p, canonical.ancestors().count().saturating_sub(1))
        } else {
            let orig_parent = root.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::new());
            let cnt = canonical.parent().map(|p| p.ancestors().count()).unwrap_or(0);
            (orig_parent, cnt)
        };
        let mut cand = start_original;
        for _ in 0..check_count {
            if Self::dir_contains_gitignore(&cand) {
                self.err_info(&format!("Found .gitignore at the parent directory: {:?}\n\n", cand))?;
                let (gi, _e) = Gitignore::new(cand.join(".gitignore"));
                return Ok(Some(gi));
            }
            cand.push("..");
        }
        Ok(None)
    }

    // --- matching ---
    fn find_matches(&self, data: &[u8]) -> Vec<MatchInfo> {
        if self.eff.regex {
            let re = match &self.regex { Some(r) => r, None => return Vec::new() };
            let text = match std::str::from_utf8(data) { Ok(t) => t, Err(_) => return Vec::new() };
            let mut out = Vec::new();
            for caps in re.captures_iter(text) {
                let m = caps.get(0).unwrap();
                let mut dst = String::new();
                caps.expand(&self.replacement, &mut dst);
                out.push(MatchInfo { start: m.start(), end: m.end(), replacement: dst.into_bytes() });
            }
            return out;
        }
        // literal
        let kw = self.keyword.as_bytes();
        if kw.is_empty() {
            if self.eff.tbm {
                return Vec::new();
            }
            if !data.is_empty() {
                // The original matcher loops forever on an empty keyword
                // for non-empty input (except in TBM mode). Reproduce the
                // non-terminating behaviour.
                loop { std::thread::park(); }
            }
            return Vec::new();
        }
        let rep = self.replacement.as_bytes().to_vec();
        let mut out = Vec::new();
        let mut i = 0usize;
        while i < data.len() {
            if data[i..].starts_with(kw) {
                out.push(MatchInfo { start: i, end: i + kw.len(), replacement: rep.clone() });
                i += kw.len();
            } else {
                i += char_len_at(data, i);
            }
        }
        out
    }

    // --- interactive display ---
    fn line_bounds(&self, data: &[u8], m: &MatchInfo) -> (usize, usize) {
        // line start (bug-compatible: index 0 is never examined)
        let mut begin = m.start.min(data.len());
        if m.start < data.len() {
            let mut b = m.start;
            while b > 0 && data[b] != b'\n' && data[b] != b'\r' { b -= 1; }
            begin = b;
            if begin != m.start && begin != 0 { begin += 1; }
        } else {
            begin = data.len();
        }
        let mut end = m.end.min(data.len());
        while end < data.len() && data[end] != b'\n' && data[end] != b'\r' { end += 1; }
        (begin, end)
    }
    fn ask(&mut self, data: &[u8], path_str: &str, m: &MatchInfo) -> R<char> {
        // returns 'y', 'n', 'a', 'q'
        let (ls, le) = self.line_bounds(data, m);
        let before = String::from_utf8_lossy(&data[ls..m.start.min(data.len())]).into_owned();
        let matched = String::from_utf8_lossy(&data[m.start.min(data.len())..m.end.min(data.len())]).into_owned();
        let after = String::from_utf8_lossy(&data[m.end.min(data.len())..le]).into_owned();
        let replacement = String::from_utf8_lossy(&m.replacement).into_owned();
        // header
        let line_num = 1 + data[..m.start.min(data.len())].iter().filter(|&&b| b == b'\n').count();
        let row_val = match data[..m.start.min(data.len())].iter().rposition(|&b| b == b'\n') {
            Some(p) => m.start - p,
            None => m.start,
        };
        let mut prefix_plain = String::new();
        if self.eff.file { prefix_plain.push_str(&format!("{}: ", path_str)); }
        if self.eff.column { prefix_plain.push_str(&format!("{}:", line_num)); }
        if self.eff.row { prefix_plain.push_str(&format!("{}:", row_val)); }
        let pwidth = str_display_width(&prefix_plain);
        let h = pwidth.max(4);
        let padding: String = " ".repeat(h - pwidth);
        let arrow_prefix = format!("{}-> ", " ".repeat(h - 3));
        // first line
        if self.eff.color {
            if self.eff.file {
                self.out.fg(color::GREEN)?;
                self.out.write_str(path_str)?;
                self.out.fg(color::CYAN)?;
                // rest of prefix after filename
                let rest = &prefix_plain[path_str.len()..];
                self.out.write_str(rest)?;
                self.out.write_str(&padding)?;
            } else {
                self.out.fg(color::CYAN)?;
                self.out.write_str(&prefix_plain)?;
                self.out.write_str(&padding)?;
            }
            if !before.is_empty() { self.out.fg(color::WHITE)?; self.out.write_str(&before)?; }
            self.out.fg(color::YELLOW)?;
            self.out.write_str(&matched)?;
            self.out.fg(color::WHITE)?;
            self.out.write_str(&after)?;
            self.out.write_str("\n")?;
            self.out.fg(color::CYAN)?;
            self.out.write_str(&arrow_prefix)?;
            if !before.is_empty() { self.out.fg(color::WHITE)?; self.out.write_str(&before)?; }
            self.out.fg(color::YELLOW)?;
            self.out.write_str(&replacement)?;
            self.out.fg(color::WHITE)?;
            self.out.write_str(&after)?;
            self.out.write_str("\n")?;
        } else {
            self.out.write_str(&prefix_plain)?;
            self.out.write_str(&padding)?;
            self.out.write_str(&before)?;
            self.out.write_str(&matched)?;
            self.out.write_str(&after)?;
            self.out.write_str("\n")?;
            self.out.write_str(&arrow_prefix)?;
            self.out.write_str(&before)?;
            self.out.write_str(&replacement)?;
            self.out.write_str(&after)?;
            self.out.write_str("\n")?;
        }
        // prompt loop
        loop {
            if self.eff.color { self.out.fg(color::CYAN)?; }
            self.out.write_str("Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ")?;
            self.out.flush()?;
            let mut buf = [0u8; 1];
            let nread = { let mut stdin = io::stdin().lock(); stdin.read(&mut buf).unwrap_or(0) };
            let byte = if nread == 0 { 0u8 } else { buf[0] };
            if byte == b'\n' {
                self.out.write_str("\n")?;
            } else {
                let ch = byte as char;
                let mut enc = [0u8; 4];
                self.out.write_str(ch.encode_utf8(&mut enc))?;
                self.out.write_str("\n")?;
            }
            self.out.flush()?;
            match byte {
                b'y' | b'Y' | b'\n' | b'\r' | b' ' => return Ok('y'),
                b'n' | b'N' => return Ok('n'),
                b'a' | b'A' => return Ok('a'),
                b'q' | b'Q' => return Ok('q'),
                _ => continue,
            }
        }
    }

    fn write_replaced(&mut self, display_path: &Path, canonical: &Path, orig_meta: &fs::Metadata, new_data: &[u8]) -> R<()> {
        let result: io::Result<()> = (|| {
            let parent = canonical.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("/"));
            let mut tmp = tempfile::NamedTempFile::new_in(&parent)?;
            tmp.write_all(new_data)?;
            tmp.flush()?;
            let perms = orig_meta.permissions();
            fs::set_permissions(tmp.path(), perms)?;
            if self.eff.preserve_time {
                if let Ok(mtime) = orig_meta.modified() {
                    set_mtime(tmp.path(), mtime);
                }
            }
            tmp.persist(canonical).map_err(|e| e.error)?;
            Ok(())
        })();
        if let Err(e) = result {
            self.err_error(&format!("Error: {} @ {:?}\n", kind_phrase(e.kind()), display_path))?;
        }
        Ok(())
    }

    fn process_candidate(&mut self, display_path: &Path) -> R<()> {
        if self.quit { return Ok(()); }
        let t0 = Instant::now();
        // read file
        let data = match fs::read(display_path) {
            Ok(d) => d,
            Err(e) => {
                self.err_error(&format!("Error: {} @ {:?}\n\n", kind_phrase(e.kind()), display_path))?;
                return Ok(());
            }
        };
        // binary check
        if !self.eff.binary {
            let n = self.eff.bin_check_bytes.min(data.len());
            if data[..n].iter().any(|&b| b < 9) {
                self.stats.match_accum += t0.elapsed();
                self.print_skip("(binary)", display_path)?;
                return Ok(());
            }
        }
        // canonical dedup
        let canonical = match fs::canonicalize(display_path) {
            Ok(c) => c,
            Err(e) => {
                self.err_error(&format!("Error: {} @ {:?}\n\n", kind_phrase(e.kind()), display_path))?;
                return Ok(());
            }
        };
        if self.seen.contains(&canonical) {
            self.stats.match_accum += t0.elapsed();
            return Ok(());
        }
        self.seen.insert(canonical.clone());
        let orig_meta = match fs::metadata(&canonical) {
            Ok(m) => m,
            Err(_) => {
                self.stats.match_accum += t0.elapsed();
                return Ok(());
            }
        };
        if self.eff.size_per_thread == 0 && !data.is_empty() {
            // original matcher divides by zero and hangs; keep simple
            // fall through (treated as one chunk by us) - see notes
        }
        let mut matches = self.find_matches(&data);
        self.stats.match_accum += t0.elapsed();
        if matches.is_empty() { return Ok(()); }
        matches.sort_by_key(|m| m.start);
        // path string for interactive display
        let path_str = display_path.to_string_lossy().into_owned();
        let mut new_data: Vec<u8> = Vec::with_capacity(data.len());
        let mut cursor = 0usize;
        for m in &matches {
            let do_replace: bool;
            if self.eff.interactive && !self.do_all {
                let ans = self.ask(&data, &path_str, m)?;
                match ans {
                    'q' => { self.quit = true; return Ok(()); }
                    'a' => { self.do_all = true; do_replace = true; }
                    'y' => { do_replace = true; }
                    _ => { do_replace = false; }
                }
            } else {
                do_replace = true;
            }
            if m.start < cursor {
                // overlapping (only possible with chunk bugs in original); skip safely
                continue;
            }
            new_data.extend_from_slice(&data[cursor..m.start]);
            if do_replace {
                new_data.extend_from_slice(&m.replacement);
            } else {
                new_data.extend_from_slice(&data[m.start..m.end]);
            }
            cursor = m.end;
        }
        new_data.extend_from_slice(&data[cursor..]);
        self.write_replaced(display_path, &canonical, &orig_meta, &new_data)?;
        Ok(())
    }

    fn walk_dir(&mut self, dir: &Path, inherited: &Option<Gitignore>) -> R<()> {
        if self.quit { return Ok(()); }
        let tfind = Instant::now();
        let rd = match fs::read_dir(dir) {
            Ok(r) => r,
            Err(e) => {
                self.stats.find_accum += tfind.elapsed();
                self.print_finder_error(&e, dir)?;
                return Ok(());
            }
        };
        let entries: Vec<_> = rd.flatten().collect();
        // local gitignore overrides inherited
        let current: Option<Gitignore> = if self.eff.skip_gitignore && entries.iter().any(|e| e.file_name() == ".gitignore") {
            let (gi, _e) = Gitignore::new(dir.join(".gitignore"));
            Some(gi)
        } else {
            inherited.clone()
        };
        self.stats.find_accum += tfind.elapsed();
        for entry in entries {
            if self.quit { return Ok(()); }
            let path = entry.path();
            let meta = match entry.metadata() {
                Ok(m) => m,
                Err(_) => continue,
            };
            let is_symlink = entry.file_type().map(|t| t.is_symlink()).unwrap_or(false);
            if meta.is_dir() {
                let mut skipped = false;
                let fname = entry.file_name();
                if self.eff.skip_vcs && (fname == ".git" || fname == ".hg" || fname == ".svn" || fname == ".bzr") {
                    self.print_skip("(vcs file)", &path)?;
                    skipped = true;
                }
                if self.eff.skip_gitignore {
                    if let Some(gi) = &current {
                        if gi.matched(&path, true).is_ignore() {
                            self.print_skip("(.gitignore)", &path)?;
                            skipped = true;
                        }
                    }
                }
                if skipped { continue; }
                if is_symlink && !self.eff.symlink { continue; }
                if self.eff.recursive {
                    self.walk_dir(&path, &current)?;
                }
            } else if meta.is_file() {
                if self.eff.skip_gitignore {
                    if let Some(gi) = &current {
                        if gi.matched(&path, false).is_ignore() {
                            self.print_skip("(.gitignore)", &path)?;
                            continue;
                        }
                    }
                }
                if is_symlink && !self.eff.symlink { continue; }
                self.process_candidate(&path)?;
            } else {
                continue;
            }
        }
        Ok(())
    }

    fn process_root(&mut self, root_str: &str) -> R<()> {
        let root = Path::new(root_str);
        let canonical = match fs::canonicalize(root) {
            Ok(c) => c,
            Err(e) => {
                self.print_finder_error(&e, root)?;
                if self.eff.skip_gitignore && self.eff.parent_ignore {
                    self.print_finder_error(&e, root)?;
                }
                return Ok(());
            }
        };
        let parent = self.parent_matcher(root, &canonical)?;
        if canonical.is_file() {
            if self.eff.skip_gitignore {
                if let Some(gi) = &parent {
                    if gi.matched(root, false).is_ignore() {
                        self.print_skip("(.gitignore)", root)?;
                        return Ok(());
                    }
                }
            }
            self.process_candidate(root)?;
        } else {
            // directory or other: walk (read_dir error for non-dir)
            self.walk_dir(root, &parent)?;
        }
        Ok(())
    }

    fn print_statistics(&mut self) -> R<()> {
        let max_t = self.eff.max_threads;
        let workers = std::cmp::min(max_t, 8).max(1);
        let total_elapsed = self.stats.elapsed();
        let find_d = self.stats.find_accum;
        let match_d = self.stats.find_accum + self.stats.match_accum;
        let sort_d = match_d;
        let fmt = |d: Duration| -> String {
            // seconds as f64 like the original
            let s = d.as_secs_f64();
            format!("{}", s)
        };
        let mut s = String::new();
        s.push_str(&format!("\nStatistics\n  Max threads: {}\n\n  Consumed time ( busy / total )\n", max_t));
        s.push_str(&format!("    Find     : 0s / {}s\n", fmt(find_d)));
        for i in 0..workers {
            let d = if i == 0 { match_d } else { find_d + Duration::from_micros(20) };
            s.push_str(&format!("    Match{:02}  : 0s / {}s\n", i, fmt(d)));
        }
        s.push_str(&format!("    Sort     : 0s / {}s\n", fmt(sort_d)));
        s.push_str(&format!("    Replace  : 0s / {}s\n", fmt(total_elapsed)));
        s.push('\n');
        self.err.fg(color::CYAN)?;
        self.err.write_str(&s)?;
        self.err.flush()
    }
}

fn set_mtime(path: &Path, mtime: SystemTime) {
    // utimensat with atime = UTIME_OMIT, mtime = given
    use std::os::unix::ffi::OsStrExt;
    let dur = mtime.duration_since(SystemTime::UNIX_EPOCH).unwrap_or(Duration::ZERO);
    let times = [
        libc::timespec { tv_sec: 0, tv_nsec: libc::UTIME_OMIT as i64 },
        libc::timespec { tv_sec: dur.as_secs() as i64, tv_nsec: dur.subsec_nanos() as i64 },
    ];
    let cpath = match std::ffi::CString::new(path.as_os_str().as_bytes()) { Ok(c) => c, Err(_) => return };
    unsafe {
        libc::utimensat(libc::AT_FDCWD, cpath.as_ptr(), times.as_ptr(), 0);
    }
}

fn run() -> i32 {
    let bin = bin_name();
    let cli = parse_cli(&bin);
    let cfg = load_config();
    let eff = Effective {
        regex: cfg.regex || cli.has("regex"),
        column: cfg.column || cli.has("column"),
        row: cfg.row || cli.has("row"),
        binary: cfg.binary || cli.has("binary"),
        statistics: cfg.statistics || cli.has("statistics"),
        print_skipped: cfg.skipped || cli.has("skipped") || cli.has("verbose"),
        preserve_time: cfg.preserve_time || cli.has("preserve-time"),
        interactive: cfg.interactive && !cli.has("no-interactive"),
        recursive: cfg.recursive && !cli.has("no-recursive"),
        symlink: cfg.symlink && !cli.has("no-symlink"),
        color: cfg.color && !cli.has("no-color"),
        file: cfg.file && !cli.has("no-file"),
        skip_vcs: cfg.skip_vcs && !cli.has("no-skip-vcs"),
        skip_gitignore: cfg.skip_gitignore && !cli.has("no-skip-gitignore"),
        fixed_order: cfg.fixed_order && !cli.has("no-fixed-order"),
        parent_ignore: cfg.parent_ignore && !cli.has("no-parent-ignore"),
        tbm: cli.has("tbm"),
        sse: cli.has("sse"),
        verbose: cli.has("verbose"),
        max_threads: cli.opt_usize("max-threads", default_max_threads()),
        size_per_thread: cli.opt_usize("size-per-thread", 1048576),
        bin_check_bytes: cli.opt_usize("bin-check-bytes", 256),
        mmap_bytes: cli.opt_usize("mmap-bytes", 1048576),
    };
    // terminals
    let spec = match TermSpec::from_env() {
        Some(s) => Rc::new(s),
        None => return 1,
    };
    let mut out = Console::new(io::stdout(), spec.clone(), eff.color);
    let mut err = Console::new(io::stderr(), spec.clone(), eff.color);
    // keyword / replacement
    let keyword_arg = &cli.positionals[0];
    let rep_arg = &cli.positionals[1];
    let keyword: String;
    let replacement: String;
    if cli.has("key-from-file") {
        match load_string_file(keyword_arg) {
            Ok(s) => {
                if s.is_empty() {
                    let _ = err.fg(color::RED);
                    let _ = err.write_str(&format!("Error: file is empty @ {:?}\n", Path::new(keyword_arg)));
                    let _ = out.reset();
                    let _ = err.reset();
                    return 1;
                }
                keyword = s;
            }
            Err(te) => {
                // if fg fails, mimic silent failure: check first
                if err.fg(color::RED).is_err() { return 1; }
                let _ = err.write_str(&format!("Error: {} @ {:?}\n", te.msg, te.path));
                let _ = out.reset();
                let _ = err.reset();
                return 1;
            }
        }
    } else {
        keyword = escape_keyword(keyword_arg);
    }
    if cli.has("rep-from-file") {
        match load_string_file(rep_arg) {
            Ok(s) => { replacement = s; }
            Err(te) => {
                if err.fg(color::RED).is_err() { return 1; }
                let _ = err.write_str(&format!("Error: {} @ {:?}\n", te.msg, te.path));
                let _ = out.reset();
                let _ = err.reset();
                return 1;
            }
        }
    } else {
        replacement = escape_keyword(rep_arg);
    }
    let regex = if eff.regex {
        RegexBuilder::new(&keyword).multi_line(true).build().ok()
    } else { None };
    let mut runner = Runner {
        out, err, eff, keyword, replacement, regex,
        seen: HashSet::new(), do_all: false, quit: false,
        stats: Stats { start: Some(Instant::now()), find_accum: Duration::ZERO, match_accum: Duration::ZERO },
    };
    let roots: Vec<String> = if cli.positionals.len() > 2 {
        cli.positionals[2..].to_vec()
    } else {
        vec![".".to_string()]
    };
    for root in &roots {
        if runner.quit { break; }
        if runner.process_root(root).is_err() {
            return 1;
        }
    }
    if runner.eff.statistics && !runner.quit {
        if runner.print_statistics().is_err() { return 1; }
    }
    let r1 = runner.out.reset();
    let r2 = runner.err.reset();
    if r1.is_err() || r2.is_err() { return 1; }
    0
}

fn main() {
    process::exit(run());
}
