fn jaro(s1: &str, s2: &str) -> f64 {
    let a: Vec<char> = s1.chars().collect(); let b: Vec<char> = s2.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; } if a.is_empty() || b.is_empty() { return 0.0; }
    let max_len = a.len().max(b.len()); let search = (max_len / 2).saturating_sub(1);
    let mut b_matched = vec![false; b.len()]; let mut a_matched = vec![false; a.len()]; let mut matches = 0usize;
    for i in 0..a.len() { let start = i.saturating_sub(search); let end = (i + search + 1).min(b.len()); for j in start..end { if !b_matched[j] && a[i] == b[j] { a_matched[i]=true; b_matched[j]=true; matches+=1; break; } } }
    if matches==0 {return 0.0;}
    let mut transpositions=0usize; let mut k=0usize; for i in 0..a.len() { if a_matched[i] { while !b_matched[k] {k+=1;} if a[i]!=b[k] {transpositions+=1;} k+=1; } }
    let m=matches as f64; (m/a.len() as f64 + m/b.len() as f64 + (m-(transpositions/2) as f64)/m)/3.0
}
fn jw(s1:&str,s2:&str)->f64{let j=jaro(s1,s2); let prefix=s1.chars().zip(s2.chars()).take(4).take_while(|(a,b)|a==b).count(); j+prefix as f64*0.1*(1.0-j)}
fn main(){for (a,b) in [("no-verbose","verbose"),("no-verbose","no-row"),("no-rep-from-file","rep-from-file"),("no-rep-from-file","no-recursive"),("no-line-by-match","no-symlink"),("no-line-by-match","symlink")] {println!("{} {} jaro {} jw {}",a,b,jaro(a,b),jw(a,b));}}
RS
