                    clear_current_temp(&tmp_path);
                    drop(tmp);
                    hang_after_replacer_panic(move || { console::byte_at(&snapshot, idx); });
                }
                let ans = match self.ask(&data, &path_str, m) {
                    Ok(a) => a,
                    Err(e) => { std::mem::forget(tmp); return Err(e); }
                };
                match ans {
                    'q' => { self.quit = true; clear_current_temp(&tmp_path); return Ok(()); }
                    'a' => { self.do_all = true; do_replace = true; }
                    'y' => { do_replace = true; }
                    _ => { do_replace = false; }
                }
            } else {
                do_replace = true;
            }
            let write_res: io::Result<()> = (|| {
                if do_replace {
                    tmp.write_all(&m.replacement)?;
                } else {
                    tmp.write_all(&data[m.start..m.end])?;
                }
                Ok(())
            })();
            if let Err(e) = write_res {
                self.err_error(&format!("Error: {} @ {:?}\\n", kind_phrase(e.kind()), display_path))?;
                return Ok(());
            }
            cursor = m.end;
        }
